function projectScalarPaths(source, schema) {
  if (!source || typeof source !== 'object') throw new TypeError('source must be an object');
  if (!Array.isArray(schema)) throw new TypeError('schema must be an array');
  const blocked = new Set(['__proto__', 'constructor', 'prototype']);
  const keys = new Set();
  for (const entry of schema) {
    if (!entry || typeof entry !== 'object' || typeof entry.key !== 'string' ||
        entry.key.length === 0 || blocked.has(entry.key) || keys.has(entry.key) ||
        !Array.isArray(entry.path) || entry.path.length === 0 ||
        entry.path.some(segment => typeof segment !== 'string' || segment.length === 0)) {
      throw new TypeError('invalid schema entry');
    }
    keys.add(entry.key);
  }

  const output = {};
  for (const entry of schema) {
    let cursor = source;
    let found = true;
    for (const segment of entry.path) {
      if (!cursor || typeof cursor !== 'object' || !(segment in cursor)) {
        found = false;
        break;
      }
      cursor = cursor[segment];
    }
    const scalar = cursor === null || typeof cursor === 'string' ||
      typeof cursor === 'boolean' || (typeof cursor === 'number' && Number.isFinite(cursor));
    output[entry.key] = found && scalar ? cursor : null;
  }
  return output;
}

module.exports = { projectScalarPaths };

