'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['projectScalarPaths']);
const { projectScalarPaths } = api;

assert.deepEqual(projectScalarPaths({}, []), {});

const inherited = { secret: 'inherited' };
const branch = Object.create(inherited);
branch.value = 'owned';
const source = Object.freeze({
  user: Object.freeze({ name: 'Ada', age: 0, enabled: false, nil: null, nested: Object.freeze({}) }),
  branch,
  primitive: 'stop',
  unsupported: Object.freeze({ value: 1 }),
  badNumber: Infinity
});
const schema = Object.freeze([
  Object.freeze({ key: 'name', path: Object.freeze(['user', 'name']) }),
  Object.freeze({ key: 'age', path: Object.freeze(['user', 'age']) }),
  Object.freeze({ key: 'enabled', path: Object.freeze(['user', 'enabled']) }),
  Object.freeze({ key: 'nil', path: Object.freeze(['user', 'nil']) }),
  Object.freeze({ key: 'missing', path: Object.freeze(['user', 'missing']) }),
  Object.freeze({ key: 'blockedTraversal', path: Object.freeze(['primitive', 'length']) }),
  Object.freeze({ key: 'inherited', path: Object.freeze(['branch', 'secret']) }),
  Object.freeze({ key: 'objectValue', path: Object.freeze(['unsupported']) }),
  Object.freeze({ key: 'nonFinite', path: Object.freeze(['badNumber']) })
]);
const result = projectScalarPaths(source, schema);
assert.deepEqual(result, {
  name: 'Ada',
  age: 0,
  enabled: false,
  nil: null,
  missing: null,
  blockedTraversal: null,
  inherited: null,
  objectValue: null,
  nonFinite: null
});
assert.deepEqual(Object.keys(result), schema.map(entry => entry.key));
assert.notStrictEqual(result, source);

for (const bad of [null, 1, 'x']) {
  assert.throws(() => projectScalarPaths(bad, []), TypeError);
}
assert.throws(() => projectScalarPaths({}, {}), TypeError);
for (const entry of [
  null,
  {},
  { key: '', path: ['x'] },
  { key: '__proto__', path: ['x'] },
  { key: 'constructor', path: ['x'] },
  { key: 'prototype', path: ['x'] },
  { key: 'x', path: [] },
  { key: 'x', path: [''] },
  { key: 'x', path: [1] }
]) {
  assert.throws(() => projectScalarPaths({}, [entry]), TypeError);
}
assert.throws(() => projectScalarPaths({}, [
  { key: 'same', path: ['a'] },
  { key: 'same', path: ['b'] }
]), TypeError);

